{
  "findings": [
    {
      "check_id": "CKV_AWS_53",
      "title": "Public ACLs are not blocked",
      "resource": "aws_s3_bucket.cloudtrail_logs",
      "severity": "HIGH",
      "explanation": "The CloudTrail log bucket has no bucket-level control blocking public ACLs, allowing a future ACL change to expose sensitive audit logs."
    },
    {
      "check_id": "CKV_AWS_54",
      "title": "Public bucket policies are not blocked",
      "resource": "aws_s3_bucket.cloudtrail_logs",
      "severity": "HIGH",
      "explanation": "The bucket does not block public bucket policies, so a future policy could unintentionally make CloudTrail logs publicly accessible."
    },
    {
      "check_id": "CKV_AWS_55",
      "title": "Public ACLs are not ignored",
      "resource": "aws_s3_bucket.cloudtrail_logs",
      "severity": "HIGH",
      "explanation": "The bucket is not configured to ignore public ACLs, leaving audit log confidentiality dependent on ACL configuration."
    },
    {
      "check_id": "CKV_AWS_56",
      "title": "Public bucket access is not restricted",
      "resource": "aws_s3_bucket.cloudtrail_logs",
      "severity": "HIGH",
      "explanation": "The bucket lacks a restriction against public access granted through bucket policies or access points."
    },
    {
      "check_id": "CKV_AWS_19",
      "title": "Default server-side encryption is not explicitly configured",
      "resource": "aws_s3_bucket.cloudtrail_logs",
      "severity": "HIGH",
      "explanation": "The file does not explicitly enforce encryption at rest for the CloudTrail log bucket, which stores security-sensitive audit records."
    },
    {
      "check_id": "CKV_AWS_21",
      "title": "Bucket versioning is disabled",
      "resource": "aws_s3_bucket.cloudtrail_logs",
      "severity": "MEDIUM",
      "explanation": "Without versioning, overwritten or deleted CloudTrail log objects cannot be recovered from prior versions."
    },
    {
      "check_id": "CKV_AWS_70",
      "title": "Unencrypted transport is permitted",
      "resource": "aws_s3_bucket.cloudtrail_logs",
      "severity": "HIGH",
      "explanation": "The bucket has no policy denying requests made without TLS, so clients could transmit audit log data over an insecure connection."
    }
  ],
  "patched_code": "resource "aws_s3_bucket" "cloudtrail_logs" {
  bucket = "fleet-management-gps-tracking-system-cloudtrail-${random_string.bucket_suffix.result}"
}

resource "aws_s3_bucket_public_access_block" "cloudtrail_logs" {
  bucket = aws_s3_bucket.cloudtrail_logs.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "cloudtrail_logs" {
  bucket = aws_s3_bucket.cloudtrail_logs.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_versioning" "cloudtrail_logs" {
  bucket = aws_s3_bucket.cloudtrail_logs.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_policy" "cloudtrail_logs" {
  bucket = aws_s3_bucket.cloudtrail_logs.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "DenyInsecureTransport"
        Effect    = "Deny"
        Principal = "*"
        Action    = "s3:*"
        Resource = [
          aws_s3_bucket.cloudtrail_logs.arn,
          "${aws_s3_bucket.cloudtrail_logs.arn}/*"
        ]
        Condition = {
          Bool = {
            "aws:SecureTransport" = "false"
          }
        }
      }
    ]
  })
}
",
  "fix_summary": "Added complete S3 public-access blocking, explicit server-side encryption, versioning, and a bucket policy that denies non-TLS requests. The existing bucket declaration and naming scheme were preserved."
}
